import React, { useEffect, useRef, useState } from 'react';
import { createChart } from 'lightweight-charts';

const PriceChart = ({ symbol, period = '1d', interval = '1m' }) => {
    const chartContainerRef = useRef(null);
    const [chart, setChart] = useState(null);
    const [series, setSeries] = useState(null);
    const [loading, setLoading] = useState(true);
    const [selectedPeriod, setSelectedPeriod] = useState('1d');

    const periods = [
        { label: '1D', value: '1d', interval: '1m' },
        { label: '1W', value: '5d', interval: '5m' },
        { label: '1M', value: '1mo', interval: '15m' },
        { label: '3M', value: '3mo', interval: '1h' },
        { label: '6M', value: '6mo', interval: '1d' },
        { label: '1Y', value: '1y', interval: '1d' },
        { label: '3Y', value: '3y', interval: '1d' },
        { label: '5Y', value: '5y', interval: '1d' },
        { label: 'ALL', value: 'max', interval: '1wk' },
    ];

    useEffect(() => {
        if (!chartContainerRef.current) return;

        const newChart = createChart(chartContainerRef.current, {
            width: chartContainerRef.current.clientWidth,
            height: 450,
            layout: {
                background: { color: '#141b2b' },
                textColor: '#e0e6ed',
            },
            grid: {
                vertLines: { color: '#2a3a5c' },
                horzLines: { color: '#2a3a5c' },
            },
            crosshair: {
                mode: 0,
            },
            timeScale: {
                borderColor: '#2a3a5c',
                timeVisible: true,
                secondsVisible: false,
            },
            rightPriceScale: {
                borderColor: '#2a3a5c',
            },
        });

        const newSeries = newChart.addCandlestickSeries({
            upColor: '#4CAF50',
            downColor: '#dc3545',
            borderVisible: false,
            wickUpColor: '#4CAF50',
            wickDownColor: '#dc3545',
        });

        setChart(newChart);
        setSeries(newSeries);

        fetchData(newSeries);

        const handleResize = () => {
            if (chartContainerRef.current) {
                newChart.resize(
                    chartContainerRef.current.clientWidth,
                    450
                );
            }
        };

        window.addEventListener('resize', handleResize);

        return () => {
            window.removeEventListener('resize', handleResize);
            newChart.remove();
        };
    }, [symbol]);

    useEffect(() => {
        // Update chart when period changes
        if (series) {
            fetchData(series);
        }
    }, [symbol, selectedPeriod]);

    const fetchData = async (seriesInstance) => {
        setLoading(true);
        try {
            const periodData = periods.find(p => p.value === selectedPeriod);
            const response = await fetch(
                `http://localhost:5000/api/historical/${symbol}?period=${periodData.value}&interval=${periodData.interval}`
            );
            const data = await response.json();
            
            if (data && data.length > 0) {
                seriesInstance.setData(data);
            }
        } catch (error) {
            console.error('Error fetching chart data:', error);
        }
        setLoading(false);
    };

    const handlePeriodChange = (periodValue) => {
        setSelectedPeriod(periodValue);
    };

    return (
        <div style={{
            background: '#141b2b',
            padding: '15px',
            borderRadius: '10px',
            border: '1px solid #2a3a5c'
        }}>
            <div style={{ 
                display: 'flex', 
                justifyContent: 'space-between', 
                alignItems: 'center',
                marginBottom: '10px',
                flexWrap: 'wrap',
                gap: '10px'
            }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
                    <h3 style={{ color: '#e0e6ed', margin: 0 }}>{symbol}</h3>
                    {loading && (
                        <span style={{ color: '#8a9bb5', fontSize: '14px' }}>Loading...</span>
                    )}
                </div>
                <div style={{ display: 'flex', gap: '4px', flexWrap: 'wrap' }}>
                    {periods.map((p) => (
                        <button
                            key={p.value}
                            onClick={() => handlePeriodChange(p.value)}
                            style={{
                                padding: '4px 10px',
                                background: selectedPeriod === p.value ? '#4CAF50' : 'transparent',
                                color: selectedPeriod === p.value ? 'white' : '#8a9bb5',
                                border: selectedPeriod === p.value ? '1px solid #4CAF50' : '1px solid #2a3a5c',
                                borderRadius: '4px',
                                cursor: 'pointer',
                                fontSize: '12px',
                                transition: 'all 0.2s'
                            }}
                        >
                            {p.label}
                        </button>
                    ))}
                </div>
            </div>
            <div ref={chartContainerRef} style={{ width: '100%', height: '450px' }} />
        </div>
    );
};

export default PriceChart;
